package com.kloda.sync

import android.content.Context
import android.os.ParcelFileDescriptor
import java.io.DataInputStream
import java.util.UUID

// Generated bytes only; diagnostic receipts/opt-in never authorize selected-source backups.
internal object AndroidS3Diagnostic {
  fun run(app: Context, profiles: AndroidS3Profiles, captured: S3Capture, request: UUID, current: () -> Boolean): Map<String, Any> {
    if (captured.profile.target.prefix.isEmpty()) throw S3Failure("invalid_request")
    fun check() { if (!current() || !profiles.current(captured)) throw S3Failure("candidate_stale") }
    check()
    val journal = AndroidS3Journal(app, profiles.journal.provider, diagnostic = true)
    try {
      journal.recoverInterrupted(); journal.setEnabled(false)
      journal.database.execSQL("CREATE TABLE IF NOT EXISTS s3_test_request(id TEXT PRIMARY KEY)")
      journal.database.execSQL("INSERT INTO s3_test_request VALUES(?)", arrayOf(request.toString()))
      journal.prepareProfile(captured.profile.target); journal.confirmProfile(captured.profile.target)
      val testProfiles = AndroidS3Profiles(app, journal)
      val snapshots = AndroidFilesSnapshots(app, s3 = journal.provider, checkPaused = ::check)
      val bytes = ByteArray(4097) { (it % 251).toByte() }
      val source = snapshots.stageMetadata(bytes)
      var retained = false
      try {
        check(); journal.setEnabled(true)
        val job = AndroidS3Job(source.id, journal.installation(), journal.context(), captured.profile.target, UUID.randomUUID().toString(),
          "diagnostic/$request", source.digest.sha256, request.toString(), source.id + ".snapshot", "objects/${journal.installation()}/${source.id}",
          source.digest.sha256, source.digest.size, "kloda-test.bin", "kloda-test.bin")
        snapshots.open(source.id, source.digest.size).use { descriptor ->
          check(); journal.insert(job); retained = true
          AndroidS3Publisher(app, testProfiles, ::check).publish(job, descriptor, { check(); true }, ::check)
        }
        check()
        val downloaded = AndroidS3Download(app, testProfiles, snapshots, ::check).stage(job.id)
        try {
          snapshots.open(downloaded.id, downloaded.digest.size).use { descriptor ->
            DataInputStream(ParcelFileDescriptor.AutoCloseInputStream(descriptor)).use { input ->
              val restored = ByteArray(bytes.size); input.readFully(restored)
              if (input.read() != -1 || !restored.contentEquals(bytes)) throw S3Failure("verification_failed")
            }
          }
        } finally { snapshots.discard(downloaded) }
        check(); journal.setEnabled(false); snapshots.discard(source); retained = false
        return mapOf("provider" to journal.provider, "state" to "completed", "id" to job.id, "size" to bytes.size, "sha256" to job.sha256)
      } catch (error: Exception) { journal.setEnabled(false); throw error }
      finally { if (!retained) snapshots.discard(source) }
    } finally { journal.database.close() }
  }
}
